start.filterFormula:
/* If the Opportunity has a related Account and the Opportunity Support Rep is not blank, and the Opportunity is new, the Support Rep is changed or the related Account is changed, run flow...*/

AND(
    NOT(ISBLANK({!$Record.AccountId})),
    NOT(ISBLANK({!$Record.Support_Rep__c})),
    OR(
        ISNEW(),
        ISCHANGED({!$Record.Support_Rep__c}),
        ISCHANGED({!$Record.AccountId})
    )
)
